import { test, expect } from '@playwright/test';

test.describe('Icon Button Accessibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/icon-buttons');
  });

  test('should have accessible names for all icon buttons', async ({ page }) => {
    // Verify all icon buttons have role="button"
    const iconButtons = page.locator('[data-testid="icon-button"]');
    await expect(iconButtons).toHaveCount(5);

    // Verify each button has a role="button"
    const roles = await iconButtons.evaluate((buttons) => buttons.map(button => button.getAttribute('role')).filter(Boolean));
    expect(roles).toHaveLength(5);
    expect(roles).toContain('button');

    // Verify each button has a descriptive name using getByRole
    const buttonNames = await iconButtons.getByRole('button');
    await expect(buttonNames).toHaveCount(5);

    // Verify each button has a visible name
    const visibleNames = await buttonNames.filter((button) => button.isVisible());
    await expect(visibleNames).toHaveCount(5);

    // Verify each visible name is not empty
    const nonEmptyNames = await visibleNames.filter((button) => button.textContent.trim().length > 0);
    await expect(nonEmptyNames).toHaveCount(5);

    // Verify all button names are accessible using getByRole
    const accessibleNames = await buttonNames.filter((button) => button.isVisible() && button.textContent.trim().length > 0);
    await expect(accessibleNames).toHaveCount(5);

    // Verify all button names are unique
    const uniqueNames = await accessibleNames.map((button) => button.textContent.trim());
    expect(new Set(uniqueNames)).toHaveSize(5);
  });

  test('should display tooltip with accessible name on hover', async ({ page }) => {
    // Locate the first icon button
    const firstButton = page.getByRole('button', { name: /edit/i });
    await expect(firstButton).toBeVisible();

    // Verify tooltip appears with accessible name
    const tooltip = page.getByTestId('icon-button-tooltip');
    await expect(tooltip).toBeVisible();

    // Verify tooltip text is accessible
    const tooltipText = page.getByText(/edit/i);
    await expect(tooltipText).toBeVisible();

    // Verify tooltip is visible when button is hovered
    await firstButton.hover();
    await expect(tooltipText).toBeVisible();

    // Verify tooltip disappears when button is not hovered
    await firstButton.unhover();
    await expect(tooltipText).not.toBeVisible();
  });
});
